// This regression is first run against the unmodified release path. The
// synthetic source is generated by projectionCase and never enters diagnostics.
func TestReuseReleasePlant(t *testing.T) {
	for _, plant := range []string{"key", "last8"} {
		t.Run(plant, func(t *testing.T) {
			m, _ := projectionCase(t, "claude-api-key")
			enableReuseFixture(t, m)
			material := m.c.material
			if plant == "last8" {
				material = material[len(material)-8:]
			}
			if err := os.WriteFile(filepath.Join(m.c.store.root, "home", "retained"), material, 0600); err != nil {
				t.Fatal("cannot plant release control")
			}
			record, _ := reviewWithdrawal(t, m, "release", true)
			if _, err := m.c.service.FinishCredentialWithdrawal(context.Background(), record, m.withdrawal); err == nil {
				t.Fatal("release admitted planted credential material")
			}
		})
	}
}

func TestReuseReleaseEvidencePath(t *testing.T) {
	for _, kind := range []string{"material", "adapter-path", "unreadable"} {
		t.Run(kind, func(t *testing.T) {
			m, _ := projectionCase(t, "claude-api-key")
			inputs := enableReuseFixture(t, m)
			path := filepath.Join(inputs.Evidence, "capture")
			if kind == "unreadable" {
				inputs.Evidence += "-absent"
				path = inputs.Evidence
			} else if os.WriteFile(path, m.c.material, 0600) != nil {
				t.Fatal("cannot plant evidence release control")
			}
			m.c.service.deps.Backend.(*reuseBackend).scanner = APIKeyReleaseScanFunc(func(ctx context.Context, _ api.CredentialProjectionAuthority, material api.SecretMaterial) (APIKeyScanResult, error) {
				result := ScanAPIKeyReleaseInputs(ctx, material, inputs)
				if kind == "adapter-path" {
					// A private adapter is not allowed to serialize its material,
					// even when it supplies an unsafe diagnostic pathname.
					raw, err := json.Marshal(result)
					if err != nil {
						t.Fatal("cannot encode adapter path control")
					}
					var rows [9]map[string]any
					if json.Unmarshal(raw, &rows) != nil {
						t.Fatal("cannot read adapter path control")
					}
					rows[5]["path"] = filepath.Join(inputs.Evidence, string(material.Bytes))
					raw, err = json.Marshal(rows)
					defer clear(raw)
					if err != nil || json.Unmarshal(raw, &result) != nil {
						t.Fatal("cannot supply adapter path control")
					}
				}
				return result, nil
			})
			record, _ := reviewWithdrawal(t, m, "release", true)
			_, finishErr := m.c.service.FinishCredentialWithdrawal(context.Background(), record, m.withdrawal)
			if finishErr == nil || !strings.Contains(finishErr.Error(), "evidence") || !strings.Contains(finishErr.Error(), inputs.Evidence) {
				t.Fatal("release refusal omitted the evidence finding path")
			}
			status, err := m.c.service.APIKeyReleaseStatus(context.Background(), m.a.ID, m.a.Request.Handoff.Spec.Runner.Slot.ID)
			if err != nil || !status.RotationRequired || status.Scan.Clean() || !strings.Contains(status.Journal, inputs.Evidence) {
				t.Fatal("retained release journal lost the finding path or quarantine")
			}
			if kind != "adapter-path" && (!strings.Contains(finishErr.Error(), strconv.Quote(path)) || !strings.Contains(status.Journal, strconv.Quote(path))) {
				t.Fatal("release refusal or journal changed the exact evidence path")
			}
			encoded, err := json.Marshal(status)
			if err != nil || bytes.Contains(encoded, m.c.material[len(m.c.material)-8:]) || strings.Contains(finishErr.Error(), string(m.c.material[len(m.c.material)-8:])) {
				t.Fatal("release diagnostics exposed credential material")
			}
			if kind != "unreadable" && os.Remove(path) != nil {
				t.Fatal("cannot collect evidence release control")
			}
			material, err := m.c.service.deps.Backend.Fetch(context.Background(), m.c.profile.Source)
			defer clear(material.Bytes)
			if err == nil || len(material.Bytes) != 0 {
				t.Fatal("finding diagnostics weakened the durable source quarantine")
			}
		})
	}
}

func enableReuseFixture(t *testing.T, m *projectionModel) APIKeyScanInputs {
	t.Helper()
	home := filepath.Join(m.c.store.root, "home")
	info, err := os.Lstat(home)
	if err != nil {
		t.Fatal("cannot pin scan fixture home")
	}
	root := t.TempDir()
	helper := filepath.Join(root, "helper.json")
	if err := os.WriteFile(helper, []byte("retained helper metadata\n"), 0600); err != nil {
		t.Fatal("cannot retain helper scan input")
	}
	inputs := APIKeyScanInputs{Home: home, HomeIdentity: info, HelperState: helper, Evidence: t.TempDir(),
		Journal: func(context.Context, string) (io.ReadCloser, error) {
			return io.NopCloser(strings.NewReader("retained unit journal\n")), nil
		}}
	if err := m.c.service.EnableAPIKeyReuseGate(APIKeyReleaseScanFunc(func(ctx context.Context, a api.CredentialProjectionAuthority, material api.SecretMaterial) (APIKeyScanResult, error) {
		if a.Request.Home != m.a.Request.Home || a.Request.Lease != m.a.Request.Lease {
			t.Fatal("scan selected a different retained home")
		}
		return ScanAPIKeyReleaseInputs(ctx, material, inputs), nil
	})); err != nil {
		t.Fatal("cannot install release gate", err)
	}
	return inputs
}

func TestReuseNextProjection(t *testing.T) {
	for _, plant := range []string{"key", "last8", "clean", "unreadable", "scanner-error"} {
		t.Run(plant, func(t *testing.T) {
			m, peer := projectionCase(t, "claude-api-key")
			inputs := enableReuseFixture(t, m)
			if plant == "scanner-error" {
				m.c.service.deps.Backend.(*reuseBackend).scanner = APIKeyReleaseScanFunc(func(_ context.Context, _ api.CredentialProjectionAuthority, material api.SecretMaterial) (APIKeyScanResult, error) {
					return APIKeyScanResult{}, errors.New(string(material.Bytes))
				})
			}
			before := []bstate.Slot{}
			for _, id := range m.a.Request.Handoff.Spec.Injection.SlotIDs {
				before = append(before, readCaseSlot(t, m.c, id))
			}
			defer clearProjectionSlots(before)
			data := m.c.material
			if plant == "last8" {
				data = data[len(data)-8:]
			}
			path := filepath.Join(inputs.Home, "retained")
			if plant != "clean" {
				if err := os.WriteFile(path, data, 0600); err != nil {
					t.Fatal("cannot plant source reuse control")
				}
			}
			if plant == "unreadable" {
				if err := os.Chmod(path, 0000); err != nil {
					t.Fatal("cannot create unreadable scan control")
				}
			}
			record, _ := reviewWithdrawal(t, m, "release", true)
			_, err := m.c.service.FinishCredentialWithdrawal(context.Background(), record, m.withdrawal)
			blocked := plant != "clean"
			if (err != nil) != blocked {
				t.Fatal("release verdict differs from its planted control")
			}
			if err != nil && (bytes.Contains([]byte(err.Error()), m.c.material) || bytes.Contains([]byte(err.Error()), m.c.material[len(m.c.material)-8:]) || !strings.Contains(err.Error(), "lane-home")) {
				t.Fatal("release refusal exposed material or omitted its fixed place")
			}
			status, err := m.c.service.APIKeyReleaseStatus(context.Background(), m.a.ID, m.a.Request.Handoff.Spec.Runner.Slot.ID)
			if err != nil || status.RotationRequired != blocked || status.Scan.Clean() == blocked || strings.Count(status.Journal, "\n") != 1 {
				t.Fatal("credential status lost its exact release verdict", err)
			}
			encoded, err := json.Marshal(status)
			if err != nil || bytes.Contains(encoded, m.c.material) || bytes.Contains(encoded, m.c.material[len(m.c.material)-8:]) {
				t.Fatal("release status or journal contains material")
			}
			// Removing the plant cannot clear a durable source quarantine.
			if blocked {
				if err := os.Remove(path); err != nil {
					t.Fatal("cannot collect planted scan control")
				}
			}
			// Model the next issuer's reserved projection using real encrypted
			// slot bytes. The retained plan/identity are fixture authorities; the
			// actual TransferCredentials path must enforce the source fence.
			m.a.ID = "projection-next"
			if err := m.c.backend.WithBroker(context.Background(), func(j bstate.Journal) error {
				for _, slot := range before {
					slot.ProjectionID = ""
					if err := j.Write("slot", slot.ID, slot); err != nil {
						return err
					}
				}
				return nil
			}); err != nil {
				t.Fatal("cannot retain next projection slots")
			}
			if err := m.c.store.save("projection-record.json", api.CredentialProjectionRecord{Authority: m.a, Generation: 1, State: "reserved"}); err != nil {
				t.Fatal("cannot reserve next projection fixture")
			}
			// Reconstruct the service to prove a new process cannot forget the
			// marker. The existing native backend still owns encrypted bytes.
			deps := m.c.service.deps
			if err := m.c.backend.Close(); err != nil {
				t.Fatal("cannot close original encrypted backend")
			}
			m.c.backend = openMutationBackend(t, m.c.directory, m.c.clock, m.c.key)
			deps.Backend = m.c.backend
			restarted, err := New(deps)
			if err != nil {
				t.Fatal("cannot reconstruct broker")
			}
			m.c.service = restarted
			enableReuseFixture(t, m)
			transfer, err := restarted.TransferCredentials(context.Background(), peer, m.a.Request)
			if (err != nil) != blocked || blocked && len(transfer.Files) != 0 || !blocked && len(transfer.Files) == 0 {
				t.Fatal("next projection ignored the durable source verdict")
			}
			if err != nil && (!strings.Contains(err.Error(), "rotation required") || bytes.Contains([]byte(err.Error()), m.c.material[len(m.c.material)-8:])) {
				t.Fatal("next projection refusal lost the source gate or exposed material")
			}
		})
	}
}

type reuseWriteFault struct {
	*measuredBackend
	at, writes int
	fired      bool
}

type reuseFaultJournal struct {
	bstate.Journal
	fault *reuseWriteFault
}

func (j reuseFaultJournal) Write(kind string, id api.ID, value any) error {
	if kind == reuseJournalKind && (strings.HasPrefix(string(id), "rs-") || strings.HasPrefix(string(id), "rr-")) {
		j.fault.writes++
		if j.fault.writes == j.fault.at {
			j.fault.fired = true
			return errors.New("interrupted release journal write")
		}
	}
	return j.Journal.Write(kind, id, value)
}

func (b *reuseWriteFault) WithBroker(ctx context.Context, fn func(bstate.Journal) error) error {
	return b.measuredBackend.WithBroker(ctx, func(j bstate.Journal) error { return fn(reuseFaultJournal{j, b}) })
}

func (b *reuseWriteFault) WithBrokerDurable(ctx context.Context, fn func(bstate.Journal) error) error {
	return b.measuredBackend.WithBrokerDurable(ctx, func(j bstate.Journal) error { return fn(reuseFaultJournal{j, b}) })
}

func TestReuseInterruptedRelease(t *testing.T) {
	for _, at := range []int{1, 2, 3} {
		t.Run(string(rune('0'+at)), func(t *testing.T) {
			m, _ := projectionCase(t, "claude-api-key")
			enableReuseFixture(t, m)
			record, _ := reviewWithdrawal(t, m, "release", true)
			gate := m.c.service.deps.Backend.(*reuseBackend)
			fault := &reuseWriteFault{measuredBackend: m.c.backend, at: at}
			gate.backend, gate.durable = fault, fault
			if _, err := m.c.service.FinishCredentialWithdrawal(context.Background(), record, m.withdrawal); err == nil || !fault.fired {
				t.Fatal("release ignored an actual journal-write interruption")
			}
			material, err := gate.Fetch(context.Background(), m.c.profile.Source)
			defer clear(material.Bytes)
			if err == nil || len(material.Bytes) != 0 {
				t.Fatal("interrupted release left its source reusable")
			}
		})
	}
}

func TestReuseStopRotation(t *testing.T) {
	for _, reason := range []string{"cancelled", "revoked"} {
		t.Run(reason, func(t *testing.T) {
			m, _ := projectionCase(t, "claude-api-key")
			enableReuseFixture(t, m)
			record, _ := reviewWithdrawal(t, m, reason, true)
			m.withdrawal.RotationRequired = true
			_, finishErr := m.c.service.FinishCredentialWithdrawal(context.Background(), record, m.withdrawal)
			if (finishErr != nil) != (reason == "revoked") {
				t.Fatal("stop or revoke changed its cleanup completion policy")
			}
			material, err := m.c.service.deps.Backend.Fetch(context.Background(), m.c.profile.Source)
			defer clear(material.Bytes)
			if err == nil || len(material.Bytes) != 0 {
				t.Fatal("stopped or revoked release lost its rotation fence")
			}
			status, err := m.c.service.APIKeyReleaseStatus(context.Background(), m.a.ID, m.a.Request.Handoff.Spec.Runner.Slot.ID)
			if err != nil || !status.RotationRequired || !status.Scan.Clean() {
				t.Fatal("stop status did not separate clean scan from rotation")
			}
		})
	}
}

func TestReuseRealStore(t *testing.T) {
	for _, plant := range []string{"key", "last8", "clean"} {
		t.Run(plant, func(t *testing.T) {
			m, _ := projectionCase(t, "claude-api-key")
			record, _ := reviewWithdrawal(t, m, "release", true)
			slot := readCaseSlot(t, m.c, m.a.Request.Handoff.Spec.Runner.Slot.ID)
			defer clear(slot.Material)
			defer clear(slot.Returned)
			completed, err := m.c.service.FinishCredentialWithdrawal(context.Background(), record, m.withdrawal)
			if err != nil {
				t.Fatal("cannot establish measured release fixture")
			}
			// Distinct helper/broker peer labels are explicit component facts.
			// This is a real-store/keystore test, not native authentication proof.
			m.a.Helper.ID = "helper-component"
			m.a.HelperPeer.HostPID = m.a.BrokerPeer.HostPID + 1
			completed.Authority = m.a
			// The real store's fixture primitive seeds the precise point between
			// its durable completion and the broker's slot-release flush. Reads
			// run all production credential-row/receipt/index validations.
			f := fx.New(t, m.c.service.deps.Config)
			f.Corrupt(t, "credential_projection_id", m.a.ID, 1, m.a.Request.Prepared.ID)
			row := struct {
				Owner      api.Actor
				ReservedAt api.Timestamp
				Record     api.CredentialProjectionRecord
			}{m.c.service.deps.ServiceScope.Actor, m.withdrawal.ObservedAt, completed}
			f.Replace(t, "credential_projection", m.a.Request.Prepared.ID, completed.Generation, row)
			if _, err := f.State.CredentialProjection(context.Background(), f.Deps.Config, m.a.Request.Prepared.ID); err != nil {
				t.Fatal("real store rejected the retained release fixture", err)
			}
			if err := m.c.backend.WithBroker(context.Background(), func(j bstate.Journal) error {
				var projection bstate.Projection
				if err := j.Read("projection", m.a.ID, &projection); err != nil {
					return err
				}
				projection.Authority = m.a
				if err := j.Write("projection", m.a.ID, projection); err != nil {
					return err
				}
				return j.Write("slot", slot.ID, slot)
			}); err != nil {
				t.Fatal("cannot restore pending release flush fixture")
			}
			deps := m.c.service.deps
			deps.Store = f.State
			service, err := New(deps)
			if err != nil {
				t.Fatal("cannot install real-store broker")
			}
			m.c.service = service
			inputs := enableReuseFixture(t, m)
			if plant != "clean" {
				data := m.c.material
				if plant == "last8" {
					data = data[len(data)-8:]
				}
				if os.WriteFile(filepath.Join(inputs.Home, "retained"), data, 0600) != nil {
					t.Fatal("cannot plant real-store control")
				}
			}
			backend, err := service.brokerBackend()
			if err != nil {
				t.Fatal("cannot open guarded real-store backend")
			}
			after := slot
			after.Material, after.Returned, after.Released = []byte{}, []byte{}, true
			err = backend.WithBroker(context.Background(), func(j bstate.Journal) error { return j.Write("slot", slot.ID, after) })
			blocked := plant != "clean"
			if (err != nil) != blocked {
				t.Fatal("real-store release did not enforce its scanned source verdict")
			}
			material, err := service.deps.Backend.Fetch(context.Background(), slot.Grant)
			defer clear(material.Bytes)
			if (err != nil) != blocked || blocked && len(material.Bytes) != 0 || !blocked && !bytes.Equal(material.Bytes, m.c.material) {
				t.Fatal("real-store source gate lost the release verdict")
			}
		})
	}
}
